#!/usr/bin/env node
// test15.mjs — Node.js port of dataset/base58/test15.py
//
// Original:
//     import argparse
//     import base58
//
//     parser = argparse.ArgumentParser()
//     parser.add_argument('--a', type=str, required=True)
//     parser.add_argument('--b', type=str, required=True)
//     parser.add_argument('--c', type=str, required=True)
//     parser.add_argument('--d', type=str, required=True)
//     args = parser.parse_args()
//
//     enc1 = base58.b58encode(args.a.encode())  # 编码字符串1
//     enc2 = base58.b58encode(args.b.encode())  # 编码字符串2
//     dec1 = base58.b58decode(args.c)  # 解码Base58字符串1
//     dec2 = base58.b58decode(args.d)  # 解码Base58字符串2
//     print(enc1)
//     print(enc2)
//     print(dec1)
//     print(dec2)
//
// All four values are computed before anything is printed, so a decoding
// failure produces no stdout at all — just the traceback and exit status 1.

import { ArgumentParser } from './lib/cli/argparse.mjs';
import { PythonError, SystemExit } from './lib/python/errors.mjs';
import { encodeUtf8 } from './lib/python/unicode.mjs';
import { printBytes } from './lib/python/print.mjs';
import { reportFatal } from './lib/python/traceback.mjs';
import { b58decode, b58encode } from './lib/base58/index.mjs';

/** Program name used in usage/help text, as in the reference build. */
const PROG = 'test15_executable';
const SOURCE_FILE = 'test15.py';
const SCRIPT_NAME = 'test15';

/**
 * The `<module>` frames a b58decode failure is reported against.  `colno` /
 * `endColno` delimit `base58.b58decode(args.X)` within the source line, which is
 * what the carets underline.
 */
const DECODE_FRAME = {
  c: { file: SOURCE_FILE, line: 13, name: '<module>', colno: 7, endColno: 31 },
  d: { file: SOURCE_FILE, line: 14, name: '<module>', colno: 7, endColno: 31 },
};

function buildParser() {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument(['--a'], { required: true });
  parser.addArgument(['--b'], { required: true });
  parser.addArgument(['--c'], { required: true });
  parser.addArgument(['--d'], { required: true });
  return parser;
}

/**
 * @param {string[]} argv arguments after the script name
 * @returns {number} process exit status
 */
export function main(argv) {
  const args = buildParser().parseArgs(argv);

  const enc1 = b58encode(encodeUtf8(args.a)); // 编码字符串1
  const enc2 = b58encode(encodeUtf8(args.b)); // 编码字符串2

  let dec1;
  let dec2;
  try {
    dec1 = b58decode(args.c); // 解码Base58字符串1
    dec2 = b58decode(args.d); // 解码Base58字符串2
  } catch (error) {
    if (!(error instanceof PythonError)) throw error;
    const frame = dec1 === undefined ? DECODE_FRAME.c : DECODE_FRAME.d;
    reportFatal(error, frame, SCRIPT_NAME, process.pid);
    return 1;
  }

  printBytes(enc1);
  printBytes(enc2);
  printBytes(dec1);
  printBytes(dec2);
  return 0;
}

try {
  process.exitCode = main(process.argv.slice(2));
} catch (error) {
  if (!(error instanceof SystemExit)) throw error;
  process.exitCode = error.code;
}
