// lib/cli/argparse.mjs
//
// A faithful subset of Python's argparse for a parser built from
// `add_argument('--x', type=str, required=True)` calls.
//
// The token classification, argument matching, error wording and error/exit
// ordering follow CPython's `ArgumentParser._parse_known_args`, so that the
// accepted and rejected command lines are the same as the reference program's:
//   * `--a V` and `--a=V` both set `a`
//   * a later occurrence overrides an earlier one
//   * a value that looks like a negative number, contains a space, or is empty
//     is accepted as a value even though it starts with '-'
//   * unique long-option prefixes are accepted (`--h` -> `--help`)
//   * everything after a bare `--` stops being an option
//   * missing required options are reported before unrecognized ones

import { SystemExit } from '../python/errors.mjs';
import { strRepr } from '../python/repr.mjs';
import { HELP, STORE, actionName, helpAction, storeAction } from './actions.mjs';
import { formatHelp, formatUsage } from './help.mjs';

/** `argparse._negative_number_matcher`. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/** Internal signal carrying argparse's "argument X: message" wording. */
class ArgumentError extends Error {
  constructor(action, message) {
    super(`argument ${actionName(action)}: ${message}`);
    this.argparseMessage = `argument ${actionName(action)}: ${message}`;
  }
}

export class ArgumentParser {
  /**
   * @param {{prog: string, addHelp?: boolean}} options
   */
  constructor(options) {
    this.prog = options.prog;
    /** @type {Array<object>} */
    this.actions = [];
    /** @type {Map<string, object>} */
    this.optionStringActions = new Map();
    this.hasNegativeNumberOptionals = false;
    if (options.addHelp !== false) this.registerAction(helpAction());
  }

  registerAction(action) {
    this.actions.push(action);
    for (const optionString of action.optionStrings) {
      this.optionStringActions.set(optionString, action);
      if (NEGATIVE_NUMBER.test(optionString)) {
        this.hasNegativeNumberOptionals = true;
      }
    }
    return action;
  }

  /** `parser.add_argument('--a', type=str, required=True)`. */
  addArgument(optionStrings, options = {}) {
    return this.registerAction(storeAction(optionStrings, options));
  }

  formatUsage() {
    return formatUsage(this.prog, this.actions);
  }

  formatHelp() {
    return formatHelp(this.prog, this.actions);
  }

  printHelp() {
    process.stdout.write(this.formatHelp());
  }

  /** `parser.error(message)`: usage + message on stderr, then exit status 2. */
  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }

  // -- token classification ------------------------------------------------

  /**
   * `_parse_optional`: decide whether a token names an option.
   * @returns {null | [object|null, string, string|null, string|null]}
   */
  parseOptional(argString) {
    if (argString.length === 0) return null;
    if (argString[0] !== '-') return null;

    if (this.optionStringActions.has(argString)) {
      return [this.optionStringActions.get(argString), argString, null, null];
    }
    if (argString.length === 1) return null;

    const equals = argString.indexOf('=');
    if (equals !== -1) {
      const optionString = argString.slice(0, equals);
      if (this.optionStringActions.has(optionString)) {
        return [
          this.optionStringActions.get(optionString),
          optionString,
          '=',
          argString.slice(equals + 1),
        ];
      }
    }

    const tuples = this.getOptionTuples(argString);
    if (tuples.length > 1) {
      const options = tuples.map((tuple) => tuple[1]).join(', ');
      this.error(`ambiguous option: ${argString} could match ${options}`);
    }
    if (tuples.length === 1) return tuples[0];

    if (NEGATIVE_NUMBER.test(argString) && !this.hasNegativeNumberOptionals) {
      return null;
    }
    if (argString.includes(' ')) return null;

    // An option-looking token that names nothing: an unrecognized argument.
    return [null, argString, null, null];
  }

  /** `_get_option_tuples`: abbreviation / concatenation matching. */
  getOptionTuples(argString) {
    const result = [];
    if (argString.startsWith('--')) {
      let optionPrefix = argString;
      let explicitArg = null;
      let sep = null;
      const equals = argString.indexOf('=');
      if (equals !== -1) {
        optionPrefix = argString.slice(0, equals);
        explicitArg = argString.slice(equals + 1);
        sep = '=';
      }
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(optionPrefix)) {
          result.push([action, optionString, sep, explicitArg]);
        }
      }
      return result;
    }

    // Single dash: `-xVALUE` may concatenate a short option with its value.
    const optionPrefix = argString;
    const shortOptionPrefix = argString.slice(0, 2);
    const shortExplicitArg = argString.slice(2);
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString === shortOptionPrefix) {
        result.push([action, optionString, '', shortExplicitArg]);
      } else if (optionString.startsWith(optionPrefix)) {
        result.push([action, optionString, null, null]);
      }
    }
    return result;
  }

  /** `_match_argument` for an optional: nargs=1 needs exactly one value token. */
  static matchArgument(action, patternTail) {
    if (action.nargs === 0) return 0;
    if (patternTail.startsWith('A')) return 1;
    throw new ArgumentError(action, 'expected one argument');
  }

  // -- parsing -------------------------------------------------------------

  /** `parse_known_args` restricted to a parser without positionals. */
  parseKnownArgs(argStrings) {
    const namespace = {};
    for (const action of this.actions) {
      if (action.kind === STORE) namespace[action.dest] = action.defaultValue;
    }

    // Classify every token: 'O' option, 'A' value, '-' the bare separator.
    const optionTuples = new Map();
    const patternParts = [];
    let afterSeparator = false;
    for (let i = 0; i < argStrings.length; i += 1) {
      const argString = argStrings[i];
      if (afterSeparator) {
        patternParts.push('A');
        continue;
      }
      if (argString === '--') {
        afterSeparator = true;
        patternParts.push('-');
        continue;
      }
      const tuple = this.parseOptional(argString);
      if (tuple === null) {
        patternParts.push('A');
      } else {
        optionTuples.set(i, tuple);
        patternParts.push('O');
      }
    }
    const pattern = patternParts.join('');

    const seen = new Set();
    const extras = [];

    const takeAction = (action, values) => {
      seen.add(action);
      if (action.kind === HELP) {
        this.printHelp();
        throw new SystemExit(0);
      }
      namespace[action.dest] = values[0];
    };

    let index = 0;
    while (index < argStrings.length) {
      const tuple = optionTuples.get(index);
      if (tuple === undefined) {
        // No positionals are defined, so a value token here is unrecognized.
        extras.push(argStrings[index]);
        index += 1;
        continue;
      }

      const [action, , , explicitArg] = tuple;
      if (action === null) {
        extras.push(argStrings[index]);
        index += 1;
        continue;
      }

      try {
        if (explicitArg !== null && explicitArg !== undefined) {
          if (ArgumentParser.matchArgument(action, 'A') === 1) {
            takeAction(action, [explicitArg]);
            index += 1;
          } else {
            throw new ArgumentError(
              action,
              `ignored explicit argument ${strRepr(explicitArg)}`,
            );
          }
        } else {
          const start = index + 1;
          const count = ArgumentParser.matchArgument(action, pattern.slice(start));
          takeAction(action, argStrings.slice(start, start + count));
          index = start + count;
        }
      } catch (error) {
        if (error instanceof ArgumentError) this.error(error.argparseMessage);
        throw error;
      }
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map(actionName);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  /** `parse_args`: like `parse_known_args`, but extras are an error. */
  parseArgs(argStrings) {
    const [namespace, extras] = this.parseKnownArgs(argStrings);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }
}

// lib/cli/help.mjs
//
// Usage and help rendering, reproducing argparse.HelpFormatter's column layout
// for a parser that only has optional arguments.

import { actionInvocation } from './actions.mjs';

const INDENT = 2;
const MAX_HELP_POSITION = 24;

/** How an action appears inside the usage line. */
function usagePart(action) {
  const body = action.nargs === 0
    ? action.optionStrings[0]
    : `${action.optionStrings[0]} ${action.metavar}`;
  return action.required ? body : `[${body}]`;
}

/** `usage: PROG [-h] --a A ...` including the trailing newline. */
export function formatUsage(prog, actions) {
  const parts = actions.map(usagePart).join(' ');
  return `usage: ${prog}${parts ? ` ${parts}` : ''}\n`;
}

/** Full `--help` output, including the trailing newline. */
export function formatHelp(prog, actions) {
  const invocations = actions.map(actionInvocation);
  const maxLength = invocations.reduce(
    (best, text) => Math.max(best, text.length + INDENT),
    0,
  );
  const helpPosition = Math.min(maxLength + 2, MAX_HELP_POSITION);
  const actionWidth = helpPosition - INDENT - 2;
  const pad = ' '.repeat(INDENT);

  let out = formatUsage(prog, actions);
  out += '\n';
  out += 'options:\n';
  actions.forEach((action, index) => {
    const invocation = invocations[index];
    if (!action.help) {
      out += `${pad}${invocation}\n`;
      return;
    }
    if (invocation.length <= actionWidth) {
      out += `${pad}${invocation.padEnd(actionWidth)}  ${action.help}\n`;
    } else {
      out += `${pad}${invocation}\n`;
      out += `${' '.repeat(helpPosition)}${action.help}\n`;
    }
  });
  return out;
}
