// lib/cli/actions.mjs
//
// The two argparse action kinds this parser needs, plus the naming helpers used
// in error and help text.

export const STORE = 'store';
export const HELP = 'help';

/**
 * @param {string[]} optionStrings e.g. ['--a']
 * @param {{required?: boolean, metavar?: string, help?: string, dest?: string}} options
 */
export function storeAction(optionStrings, options = {}) {
  const dest = options.dest ?? optionStrings[0].replace(/^-+/, '').replace(/-/g, '_');
  return {
    kind: STORE,
    optionStrings,
    dest,
    nargs: 1,
    required: options.required === true,
    metavar: options.metavar ?? dest.toUpperCase(),
    help: options.help,
    defaultValue: null,
  };
}

export function helpAction(optionStrings = ['-h', '--help']) {
  return {
    kind: HELP,
    optionStrings,
    dest: 'help',
    nargs: 0,
    required: false,
    metavar: undefined,
    help: 'show this help message and exit',
    defaultValue: undefined,
  };
}

/** `argparse._get_action_name` — how an action is named in error messages. */
export function actionName(action) {
  if (action.optionStrings.length > 0) return action.optionStrings.join('/');
  if (action.metavar !== undefined) return action.metavar;
  return action.dest;
}

/** `HelpFormatter._format_action_invocation`. */
export function actionInvocation(action) {
  if (action.nargs === 0) return action.optionStrings.join(', ');
  return action.optionStrings
    .map((optionString) => `${optionString} ${action.metavar}`)
    .join(', ');
}

